use sarv_quote::{store::Store,domain::DateDisplay,export};
use std::{path::Path,fs};
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().collect();let p=Path::new(&args[1]);fs::create_dir_all(p)?;let old=Store::restore_preview(Path::new(&args[2]))?;let quotes=serde_json::to_value(&old.quotes)?;let dates=old.quotes.iter().map(|q|(&q.quote_date,&q.valid_until)).collect::<Vec<_>>();assert_eq!(old.quotes.len(),3);assert!(old.quotes.iter().all(|q|q.date_display!=DateDisplay::Jalali));let before=old.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>,_>>()?;let mut s=Store::open(&p.join("legacy-restored"))?;s.restore(old.clone())?;s.change(|state|{state.settings.date_display=DateDisplay::Jalali;Ok(())})?;assert_eq!(quotes,serde_json::to_value(&s.state.quotes)?);assert_eq!(before,s.state.quotes.iter().map(export::csv_bytes).collect::<Result<Vec<_>,_>>()?);s.backup(&p.join("legacy-jalali-preference.json"))?;let expected=serde_json::to_value(&s.state)?;drop(s);let s=Store::open(&p.join("legacy-restored"))?;assert_eq!(expected,serde_json::to_value(&s.state)?);export::pdf(&s.state.quotes[0],&p.join("retained-m1-quote.pdf"))?;println!("PASS actual retained M1 schema2 fixture:3 quotes and all revisions/date snapshots/CSV exact after Jalali preference+restart; original dates {dates:?}");Ok(())}
